{
  "name": "unpipe-server",
  "version": "1.0.0",
  "description": "Node.js server that reliably unpipes a stream from all of its destinations",
  "main": "index.js",
  "type": "commonjs",
  "scripts": {
    "start": "node index.js",
    "test": "node --test"
  },
  "dependencies": {
    "unpipe": "^1.0.0"
  },
  "engines": {
    "node": ">=18"
  }
}

"use strict";

const http = require("http");
const { Readable } = require("stream");
const unpipe = require("unpipe");

const PORT = process.env.PORT || 3000;

function createSource() {
  let n = 0;
  return new Readable({
    read() {
      if (n >= 10) {
        this.push(null);
        return;
      }
      this.push(`chunk ${++n}\n`);
    },
  });
}

function streamTo(res) {
  const source = createSource();

  const stop = () => {
    unpipe(source);
    if (!res.writableEnded) res.end("\n[unpiped from all destinations]\n");
  };

  source.pipe(res);
  res.on("close", stop);

  return source;
}

const server = http.createServer((req, res) => {
  if (req.url === "/stream") {
    res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" });
    streamTo(res);
    return;
  }

  if (req.url === "/health") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ status: "ok" }));
    return;
  }

  res.writeHead(404, { "Content-Type": "text/plain" });
  res.end("Not Found\n");
});

if (require.main === module) {
  server.listen(PORT, () => {
    console.log(`server listening on http://localhost:${PORT}`);
  });
}

module.exports = { server, streamTo, createSource };

"use strict";

const test = require("node:test");
const assert = require("node:assert");
const { PassThrough } = require("stream");
const unpipe = require("unpipe");
const { createSource } = require("../index");

test("unpipes a stream from all destinations", async () => {
  const source = createSource();
  const a = new PassThrough();
  const b = new PassThrough();

  let aChunks = 0;
  let bChunks = 0;
  a.on("data", () => aChunks++);
  b.on("data", () => bChunks++);

  source.pipe(a);
  source.pipe(b);

  await new Promise((resolve) => setImmediate(resolve));
  const seenBefore = aChunks;
  assert.ok(seenBefore > 0, "destination received data before unpipe");

  unpipe(source);

  const after = { a: aChunks, b: bChunks };
  await new Promise((resolve) => setTimeout(resolve, 20));

  assert.strictEqual(aChunks, after.a);
  assert.strictEqual(bChunks, after.b);
});
